compliant.code:
try:
    do_something()
except ValueError as e:
    handle_error(e)
finally:
    cleanup()  # No raise statement

try:
    do_something()
except ValueError as e:
    handle_error(e)
finally:
    if some_condition:
        raise RuntimeError("Explicit exception")  # Explicit exception

